    var owner = (projectConfig.repository.owner) || p.owner;
    var repo  = (projectConfig.repository.repo)  || p.repo;
    if ((!owner || !repo) && typeof repo === 'string' && repo.indexOf('/') !== -1) {
        var seg = repo.split('/');
        owner = owner || seg[0];
        repo = seg[1];
