        if (isConfigDiscovery) return null;

        // Forward agent JSON / JS reads to disk
        // Try with agents/ prefix first (submodule layout), then without (standalone)
        try {
            var result = file_read(readOpts);
            if (result) return result;
        } catch (e) {}
