function resolveValidationConcurrency(jobParams, projectCfg) {
    var out = { max: 1, watermark: 3, minutesEstimate: 35 };
    function pick(jsonVal, cfgVal, name) {
        // Repo variables arrive as strings — accept the '5' form too.
