    function pr(n, extra) {
        var it = { key: 'pr-' + n, labels: ['pr_approved'], issueNumber: null, prNumber: n,
            branch: 'ai/x-' + n, headSha: OLD, draft: false };
        if (extra) { for (var k in extra) { if (extra.hasOwnProperty(k)) it[k] = extra[k]; } }
        return it;
    }

    function config(owner, repo) {
