        });
        assert.equal(ciDispatches(sm).length, 0, 'nothing to validate');
        assert.equal(sm.capturedTriggers.length, 3, 'all 3 slots go to reviews');
        assert.ok((sm.capturedLogs || []).some(function (l) {
