suite('smAgent: silent-update failure stderr tail (gh-1074)', function () {
    var RULE_1074 = { source: 'github', query: { type: 'pr', labels: ['pr_approved'], mergeState: 'BEHIND' },
                      localAction: 'update_branch', limit: 5, id: 'silent-update-behind' };
