    function makeStderrFileRead(stderrByPath) {
        return function (readOpts) {
            var p = readOpts.path;
            if (stderrByPath[p] !== undefined) return stderrByPath[p];
            return p === CONFIG_1074_PATH ? CONFIG_1074 : null;
