        var v = cfg[tier];
        if (typeof v === 'string' && v.trim() !== '') {
            out[tier] = v;
        } else if (typeof v !== 'undefined') {
            console.warn('  ⚠️  config.smPriorityLabels.' + tier +
                ' ignored — not a non-empty string: ' + JSON.stringify(v));
        }
    });
    return out;
}

