    // token-URL patterns in file writes (the repo's TOK convention)
    var TOK_1074 = 'token:'[REDACTED:Sensitive Value]'ghp_' + '[REDACTED:High Entropy String]' + '@';
    var RAW_TOKEN_1074 = 'ghp_' + '[REDACTED:High Entropy String]';

