    var _testModule_ = { exports: {} };
    var _testRequire_ = requireFn || function(id) {
        throw new Error('loadModule: require("' + id + '") not provided for ' + path);
    };

    // eval runs in current scope — can access _testMocks_, _testModule_, _testRequire_
