        }
        lines.push(' ! [remote rejected] HEAD:ai/gh-1591 (protected branch hook declined)');
        lines.push("error: failed to push some refs to 'https://github.com/" + FORK_1074 + ".git'");
        return lines.join('\n') + '\n';
