        assert.ok(/2>\/tmp\/sm-silent-update-\S+\.stderr/.test(cmd), 'clone stderr redirect present');
        assert.ok(/; \} 2>>\/tmp\/sm-silent-update-\S+\.stderr && rm -f \/tmp\/sm-silent-update-\S+\.stderr$/.test(cmd),
